using MarketSphere.Domain.Entities.CRM;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace MarketSphere.Infrastructure.Persistence.Configurations.CRM;
public sealed class CRMActivityConfiguration : IEntityTypeConfiguration<CRMActivity> { public void Configure(EntityTypeBuilder<CRMActivity> b) { b.ToTable("CRMActivities", t => { t.HasCheckConstraint("CK_CRMActivities_RelatedEntity", "[LeadID] IS NOT NULL OR [ClientID] IS NOT NULL OR [OpportunityID] IS NOT NULL"); t.HasCheckConstraint("CK_CRMActivities_Schedule", "[ScheduledEndAt] IS NULL OR [ScheduledStartAt] IS NULL OR [ScheduledEndAt] >= [ScheduledStartAt]"); }); b.HasKey(x => x.CRMActivityID); b.Property(x => x.Subject).HasMaxLength(200).IsRequired(); b.Property(x => x.Details).HasColumnType("nvarchar(max)"); b.Property(x => x.LocationOrMeetingLink).HasMaxLength(500); b.Property(x => x.Agenda).HasColumnType("nvarchar(max)"); b.Property(x => x.Outcome).HasColumnType("nvarchar(max)"); b.HasIndex(x => new { x.LeadID, x.ClientID, x.OpportunityID, x.ActivityAt }); b.HasOne(x => x.Lead).WithMany().HasForeignKey(x => x.LeadID).OnDelete(DeleteBehavior.Restrict); b.HasOne(x => x.Client).WithMany().HasForeignKey(x => x.ClientID).OnDelete(DeleteBehavior.Restrict); b.HasOne(x => x.Opportunity).WithMany().HasForeignKey(x => x.OpportunityID).OnDelete(DeleteBehavior.Restrict); b.HasOne(x => x.PerformedByEmployee).WithMany().HasForeignKey(x => x.PerformedByEmployeeID).OnDelete(DeleteBehavior.Restrict); } }
